-- Ensure Solar Services is present under the permanent Home Services category.
-- The primary key is generated by the target environment; application code
-- resolves this fixed allowlisted Vendor route by the Solar Services name.
WITH next_home_service_order AS (
    SELECT COALESCE(MAX(sort_order) + 1, 0) AS sort_order
    FROM sub_categories
    WHERE main_category_id = 37
)
INSERT INTO sub_categories (main_category_id, name, is_active, sort_order, description)
SELECT 37, 'Solar Services', TRUE, next_home_service_order.sort_order, 'Solar Services'
FROM next_home_service_order
WHERE EXISTS (SELECT 1 FROM main_categories WHERE id = 37)
  AND NOT EXISTS (
      SELECT 1 FROM sub_categories
      WHERE main_category_id = 37 AND LOWER(name) = 'solar services'
  );
